CREATE TABLE IF NOT EXISTS health_daily(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,date TEXT NOT NULL,source TEXT NOT NULL,steps REAL,distance_m REAL,active_kcal REAL,resting_hr REAL,avg_hr REAL,max_hr REAL,sleep_min REAL,weight_kg REAL,updated INTEGER NOT NULL,PRIMARY KEY(user_id,date,source));
CREATE TABLE IF NOT EXISTS health_consent(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,accepted INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS health_tokens(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,hash TEXT UNIQUE NOT NULL,scope TEXT NOT NULL,last_received INTEGER);
CREATE TABLE IF NOT EXISTS health_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS health_connections(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider TEXT NOT NULL,tokens TEXT NOT NULL,expires INTEGER NOT NULL,last_sync INTEGER,retry_at INTEGER DEFAULT 0,PRIMARY KEY(user_id,provider));
CREATE TABLE IF NOT EXISTS health_flows(state TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider TEXT NOT NULL,verifier TEXT NOT NULL,expires INTEGER NOT NULL,preview INTEGER NOT NULL DEFAULT 0);
